{"sql": "WITH inst AS (
 SELECT instrument FROM jwst_space_images WHERE instrument IN ('NIRCam','MIRI','NIRSpec','NIRISS','FGS') GROUP BY 1 HAVING COUNT(*) >= 20
), valid AS (
 SELECT instrument, date_taken FROM jwst_space_images
 WHERE instrument IN (SELECT instrument FROM inst) AND date_taken >= '2022-07-12' AND date_taken <= TIMESTAMP '2026-10-05'
), gaps AS (
 SELECT instrument, date_taken AS end_date,
 date_diff('day', CAST(LAG(date_taken) OVER (PARTITION BY instrument ORDER BY date_taken) AS DATE), CAST(date_taken AS DATE)) AS gap_days
 FROM valid
), best AS (
 SELECT instrument, gap_days, end_date,
 ROW_NUMBER() OVER (PARTITION BY instrument ORDER BY gap_days DESC, end_date) AS rn
 FROM gaps WHERE gap_days IS NOT NULL
), pct AS (
 SELECT instrument, ROUND(100.0 * SUM(CASE WHEN modality='spectrum_or_plot' THEN 1 ELSE 0 END) / COUNT(*), 1) AS pct_spectra_or_plots
 FROM jwst_space_images WHERE instrument IN (SELECT instrument FROM inst) GROUP BY 1
)
SELECT b.instrument, b.gap_days, b.end_date, p.pct_spectra_or_plots
FROM best b JOIN pct p USING(instrument) WHERE rn = 1 ORDER BY instrument"}

{"sql": "with b as (
  select year(p.date_taken) as yr, l.gate_category, j.photo_id is null as excluded
  from photos p join labels l using(photo_id) left join jwst_space_images j using(photo_id)
  where p.date_taken >= '2022-01-01' and p.date_taken < '2026-01-01'
), tot as (
  select yr, count(*) as labelled, round(100.0*avg(excluded::int),1) as pct_not_published from b group by yr
), top as (
  select yr, gate_category, row_number() over (partition by yr order by count(*) desc, gate_category) rn
  from b where excluded group by yr, gate_category
)
select t.yr as year, t.labelled as labelled_count, t.pct_not_published, top.gate_category as top_excluded_gate_category
from tot t left join top on top.yr = t.yr and top.rn = 1 order by t.yr"}
